// tsr_bw_kernel.sv — the M0 DMA bandwidth kernel body (docs/bandwidth-kernel.md): a Vitis RTL kernel with
// per-channel AXI4 ports as packed [NUM_CH] vectors. The packaged kernel tsr_bw_k4 (generated by
// gen_bw.py) instantiates it with NUM_CH 4 and named ports m_axi_ch<c>_*; the Verilator bench
// (tb/platform/bw) drives it directly and through the packaged top.
//
// Owner: m0bw agent (docs/bandwidth-kernel.md).
//
// Interface: ap_clk, ap_rst_n (active low, synchronous), interrupt, s_axi_control (AXI4-Lite,
// 32-bit data, 12-bit address; register map in tsr_bw_ctrl), m_axi_*[c] (AXI4, 512-bit data,
// 64-bit address, 4-bit ID; the adapter's tsr_xrt_axi_bridge per channel: AxADDR = buffer
// address + beat * 64, AxSIZE 6, INCR, AxCACHE 0011, WSTRB all ones, AXI_SLICES register slices
// on every channel).
//
//   ap_rst_n -> tsr_xrt_reset -+-> tsr_bw_ctrl <-> s_axi_control, interrupt
//                              |       | go / done toggles (CTRL_PIPE stages), config snapshot,
//                              |       | result reads
//                              +-> per channel c: tsr_bw_engine[c] -> tsr_xrt_axi_bridge[c] <-> m_axi_*[c]
// Engine and bridge of a channel take their reset copies from rst_ch_n[c] (equal copies, one per
// part: the bridge's four and the engine's), so all of them can sit next to the channel's DDR4
// controller; everything between the control block and an engine is registered on
// both sides (toggles through CTRL_PIPE stages, the config snapshot is static during a run, the
// result path is registered in the engine and in the control block).

module tsr_bw_kernel
  import tsr_pkg::*;
#(
  parameter int unsigned NUM_CH      = 4,
  parameter int unsigned ADDR_BEAT_W = TSR_DEF_ADDR_BEAT_W,   // 16 GiB per channel
  parameter int unsigned AXI_SLICES  = 2,
  parameter int unsigned CTRL_PIPE   = 2                      // >= 1: toggle stages each way
) (
  input  logic                                 ap_clk,
  input  logic                                 ap_rst_n,
  // Vitis names the interrupt port `interrupt`, a C++ keyword for Verilator's model
  /* verilator lint_off SYMRSVDWORD */
  output logic                                 interrupt,
  /* verilator lint_on SYMRSVDWORD */

  // ---- s_axi_control ----
  input  logic                                 s_axi_control_awvalid,
  output logic                                 s_axi_control_awready,
  input  logic [11:0]                          s_axi_control_awaddr,
  input  logic                                 s_axi_control_wvalid,
  output logic                                 s_axi_control_wready,
  input  logic [31:0]                          s_axi_control_wdata,
  input  logic [3:0]                           s_axi_control_wstrb,
  output logic                                 s_axi_control_bvalid,
  input  logic                                 s_axi_control_bready,
  output logic [1:0]                           s_axi_control_bresp,
  input  logic                                 s_axi_control_arvalid,
  output logic                                 s_axi_control_arready,
  input  logic [11:0]                          s_axi_control_araddr,
  output logic                                 s_axi_control_rvalid,
  input  logic                                 s_axi_control_rready,
  output logic [31:0]                          s_axi_control_rdata,
  output logic [1:0]                           s_axi_control_rresp,

  // ---- m_axi, one per channel ----
  output logic [NUM_CH-1:0]                    m_axi_awvalid,
  input  logic [NUM_CH-1:0]                    m_axi_awready,
  output logic [NUM_CH-1:0][63:0]              m_axi_awaddr,
  output logic [NUM_CH-1:0][7:0]               m_axi_awlen,
  output logic [NUM_CH-1:0][2:0]               m_axi_awsize,
  output logic [NUM_CH-1:0][1:0]               m_axi_awburst,
  output logic [NUM_CH-1:0]                    m_axi_awlock,
  output logic [NUM_CH-1:0][3:0]               m_axi_awcache,
  output logic [NUM_CH-1:0][2:0]               m_axi_awprot,
  output logic [NUM_CH-1:0][3:0]               m_axi_awqos,
  output logic [NUM_CH-1:0][TSR_MEM_ID_W-1:0]  m_axi_awid,
  output logic [NUM_CH-1:0]                    m_axi_wvalid,
  input  logic [NUM_CH-1:0]                    m_axi_wready,
  output logic [NUM_CH-1:0][511:0]             m_axi_wdata,
  output logic [NUM_CH-1:0][63:0]              m_axi_wstrb,
  output logic [NUM_CH-1:0]                    m_axi_wlast,
  input  logic [NUM_CH-1:0]                    m_axi_bvalid,
  output logic [NUM_CH-1:0]                    m_axi_bready,
  input  logic [NUM_CH-1:0][1:0]               m_axi_bresp,
  input  logic [NUM_CH-1:0][TSR_MEM_ID_W-1:0]  m_axi_bid,
  output logic [NUM_CH-1:0]                    m_axi_arvalid,
  input  logic [NUM_CH-1:0]                    m_axi_arready,
  output logic [NUM_CH-1:0][63:0]              m_axi_araddr,
  output logic [NUM_CH-1:0][7:0]               m_axi_arlen,
  output logic [NUM_CH-1:0][2:0]               m_axi_arsize,
  output logic [NUM_CH-1:0][1:0]               m_axi_arburst,
  output logic [NUM_CH-1:0]                    m_axi_arlock,
  output logic [NUM_CH-1:0][3:0]               m_axi_arcache,
  output logic [NUM_CH-1:0][2:0]               m_axi_arprot,
  output logic [NUM_CH-1:0][3:0]               m_axi_arqos,
  output logic [NUM_CH-1:0][TSR_MEM_ID_W-1:0]  m_axi_arid,
  input  logic [NUM_CH-1:0]                    m_axi_rvalid,
  output logic [NUM_CH-1:0]                    m_axi_rready,
  input  logic [NUM_CH-1:0][511:0]             m_axi_rdata,
  input  logic [NUM_CH-1:0][1:0]               m_axi_rresp,
  input  logic [NUM_CH-1:0]                    m_axi_rlast,
  input  logic [NUM_CH-1:0][TSR_MEM_ID_W-1:0]  m_axi_rid
);

  if (CTRL_PIPE < 1) begin : g_chk_pipe
    $fatal(1, "tsr_bw_kernel: CTRL_PIPE must be >= 1");
  end

  // -------------------------------------------------------------------------------------------
  // Reset distribution (the adapter's: per-channel copies, one for each of the bridge's reset
  // parts as in tsr_xrt_kernel and one for the engine with its toggles; the "core" copy is not
  // used)
  // -------------------------------------------------------------------------------------------
  localparam int unsigned CNT_RST = 4;                 // bridge counter reset copies
  localparam int unsigned BR_RST  = 4 + 2 * CNT_RST;   // [0 +: BR_RST] tsr_xrt_axi_bridge parts
  localparam int unsigned CH_RST  = BR_RST + 1;        // [BR_RST] engine and toggles
  logic                          rst_ctrl_n, rst_core_n;
  logic [NUM_CH-1:0][CH_RST-1:0] rst_ch_n;

  tsr_xrt_reset #(.N_CH(NUM_CH), .CH_COPIES(CH_RST), .CORE_STAGES(2)) u_rst (
    .clk(ap_clk), .rst_in_n(ap_rst_n), .rst_ctrl_n, .rst_ch_n, .rst_core_n
  );

  wire unused_ok = &{1'b0, rst_core_n};

  // -------------------------------------------------------------------------------------------
  // Control block
  // -------------------------------------------------------------------------------------------
  logic                     go_tgl;
  logic [NUM_CH-1:0]        done_tgl;
  logic [31:0]              seed;
  logic [NUM_CH-1:0][31:0]  ch_ctrl, res_rdata;
  logic [NUM_CH-1:0][63:0]  ch_bytes, ch_rd_off, ch_wr_off, ch_base;
  logic [3:0]               res_sel;

  tsr_bw_ctrl #(.NUM_CH(NUM_CH), .ADDR_BEAT_W(ADDR_BEAT_W), .AXI_SLICES(AXI_SLICES)) u_ctrl (
    .clk(ap_clk), .rst_n(rst_ctrl_n),
    .s_awvalid(s_axi_control_awvalid), .s_awready(s_axi_control_awready), .s_awaddr(s_axi_control_awaddr),
    .s_wvalid(s_axi_control_wvalid), .s_wready(s_axi_control_wready), .s_wdata(s_axi_control_wdata),
    .s_wstrb(s_axi_control_wstrb),
    .s_bvalid(s_axi_control_bvalid), .s_bready(s_axi_control_bready), .s_bresp(s_axi_control_bresp),
    .s_arvalid(s_axi_control_arvalid), .s_arready(s_axi_control_arready), .s_araddr(s_axi_control_araddr),
    .s_rvalid(s_axi_control_rvalid), .s_rready(s_axi_control_rready), .s_rdata(s_axi_control_rdata),
    .s_rresp(s_axi_control_rresp),
    .irq(interrupt),
    .go_tgl, .done_tgl, .seed, .ch_ctrl, .ch_bytes, .ch_rd_off, .ch_wr_off, .ch_base, .res_sel, .res_rdata
  );

  // -------------------------------------------------------------------------------------------
  // Channels
  // -------------------------------------------------------------------------------------------
  for (genvar c = 0; c < NUM_CH; c++) begin : g_ch
    // toggles: CTRL_PIPE stages each way (reset with the channel: a reset returns both to 0)
    logic [CTRL_PIPE-1:0] go_p, done_p;
    logic                 e_done;
    always_ff @(posedge ap_clk) begin
      if (!rst_ch_n[c][BR_RST]) begin
        go_p   <= '0;
        done_p <= '0;
      end else begin
        go_p   <= CTRL_PIPE'({go_p, go_tgl});      // go_p[0] newest, go_p[CTRL_PIPE-1] to the engine
        done_p <= CTRL_PIPE'({done_p, e_done});
      end
    end
    assign done_tgl[c] = done_p[CTRL_PIPE-1];

    logic                         rd_req_valid, rd_req_ready, rd_rsp_valid, rd_rsp_ready, rd_rsp_last;
    logic [ADDR_BEAT_W-1:0]       rd_req_addr, wr_req_addr;
    logic [TSR_LEN_W-1:0]         rd_req_len, wr_req_len;
    logic [TSR_MEM_ID_W-1:0]      rd_req_id, rd_rsp_id, wr_req_id, wr_rsp_id;
    logic [511:0]                 rd_rsp_data, wr_dat_data;
    logic                         wr_req_valid, wr_req_ready, wr_dat_valid, wr_dat_ready, wr_dat_last;
    logic                         wr_rsp_valid, wr_rsp_ready;
    logic                         ev_rresp_err, ev_bresp_err, ev_unexpected;
    logic [63:0]                  base;

    tsr_bw_engine #(.CH(c), .ADDR_BEAT_W(ADDR_BEAT_W)) u_eng (
      .clk(ap_clk), .rst_n(rst_ch_n[c][BR_RST]),
      .go_tgl(go_p[CTRL_PIPE-1]), .done_tgl(e_done),
      .cfg_ctrl(ch_ctrl[c]), .cfg_seed(seed), .cfg_bytes(ch_bytes[c]), .cfg_rd_off(ch_rd_off[c]),
      .cfg_wr_off(ch_wr_off[c]), .cfg_base(ch_base[c]), .base,
      .res_sel, .res_rdata(res_rdata[c]),
      .rd_req_valid, .rd_req_ready, .rd_req_addr, .rd_req_len, .rd_req_id,
      .rd_rsp_valid, .rd_rsp_ready, .rd_rsp_data, .rd_rsp_id, .rd_rsp_last,
      .wr_req_valid, .wr_req_ready, .wr_req_addr, .wr_req_len, .wr_req_id,
      .wr_dat_valid, .wr_dat_ready, .wr_dat_data, .wr_dat_last,
      .wr_rsp_valid, .wr_rsp_ready, .wr_rsp_id,
      .ev_rresp_err, .ev_bresp_err, .ev_unexpected
    );

    tsr_xrt_axi_bridge #(.ADDR_BEAT_W(ADDR_BEAT_W), .BEAT_BITS(512), .SLICES(AXI_SLICES), .CNT_RST(CNT_RST)) u_br (
      .clk(ap_clk), .rst_n(rst_ch_n[c][0]), .rst_axi_n(rst_ch_n[c][1]), .rst_rd_n(rst_ch_n[c][2]),
      .rst_wr_n(rst_ch_n[c][3]), .rst_rdc_n(rst_ch_n[c][4 +: CNT_RST]),
      .rst_wrc_n(rst_ch_n[c][4 + CNT_RST +: CNT_RST]), .base,
      .c_rd_req_valid(rd_req_valid), .c_rd_req_ready(rd_req_ready), .c_rd_req_addr(rd_req_addr),
      .c_rd_req_len(rd_req_len), .c_rd_req_id(rd_req_id),
      .c_rd_rsp_valid(rd_rsp_valid), .c_rd_rsp_ready(rd_rsp_ready), .c_rd_rsp_data(rd_rsp_data),
      .c_rd_rsp_id(rd_rsp_id), .c_rd_rsp_last(rd_rsp_last),
      .c_wr_req_valid(wr_req_valid), .c_wr_req_ready(wr_req_ready), .c_wr_req_addr(wr_req_addr),
      .c_wr_req_len(wr_req_len), .c_wr_req_id(wr_req_id),
      .c_wr_dat_valid(wr_dat_valid), .c_wr_dat_ready(wr_dat_ready), .c_wr_dat_data(wr_dat_data), .c_wr_dat_mask('1),
      .c_wr_dat_last(wr_dat_last),
      .c_wr_rsp_valid(wr_rsp_valid), .c_wr_rsp_ready(wr_rsp_ready), .c_wr_rsp_id(wr_rsp_id),
      .m_axi_awvalid(m_axi_awvalid[c]), .m_axi_awready(m_axi_awready[c]), .m_axi_awaddr(m_axi_awaddr[c]),
      .m_axi_awlen(m_axi_awlen[c]), .m_axi_awsize(m_axi_awsize[c]), .m_axi_awburst(m_axi_awburst[c]),
      .m_axi_awlock(m_axi_awlock[c]), .m_axi_awcache(m_axi_awcache[c]), .m_axi_awprot(m_axi_awprot[c]),
      .m_axi_awqos(m_axi_awqos[c]), .m_axi_awid(m_axi_awid[c]),
      .m_axi_wvalid(m_axi_wvalid[c]), .m_axi_wready(m_axi_wready[c]), .m_axi_wdata(m_axi_wdata[c]),
      .m_axi_wstrb(m_axi_wstrb[c]), .m_axi_wlast(m_axi_wlast[c]),
      .m_axi_bvalid(m_axi_bvalid[c]), .m_axi_bready(m_axi_bready[c]), .m_axi_bresp(m_axi_bresp[c]),
      .m_axi_bid(m_axi_bid[c]),
      .m_axi_arvalid(m_axi_arvalid[c]), .m_axi_arready(m_axi_arready[c]), .m_axi_araddr(m_axi_araddr[c]),
      .m_axi_arlen(m_axi_arlen[c]), .m_axi_arsize(m_axi_arsize[c]), .m_axi_arburst(m_axi_arburst[c]),
      .m_axi_arlock(m_axi_arlock[c]), .m_axi_arcache(m_axi_arcache[c]), .m_axi_arprot(m_axi_arprot[c]),
      .m_axi_arqos(m_axi_arqos[c]), .m_axi_arid(m_axi_arid[c]),
      .m_axi_rvalid(m_axi_rvalid[c]), .m_axi_rready(m_axi_rready[c]), .m_axi_rdata(m_axi_rdata[c]),
      .m_axi_rresp(m_axi_rresp[c]), .m_axi_rlast(m_axi_rlast[c]), .m_axi_rid(m_axi_rid[c]),
      .ev_rresp_err, .ev_bresp_err, .ev_unexpected
    );
  end

endmodule
